head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.gSndlocTp = $c.frame.path("../frame_head").gSndlocTpCd;
scwin.gAcptNo = $c.frame.path("../frame_head").scwin.gAcptNo;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gDepCd = js_dep_cd;
scwin.gDutyGrp = js_gduty;
scwin.gDutyYn = js_duty;
scwin.gEmpNo = js_emp_no; // 세션정보 	
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gDoc_LdMktTp = $c.frame.path("../frame_head").scwin.gDoc_LdMktTp;
scwin.gProcsCd = ""; //처리상태코드
scwin.gFormWarnContn = $c.frame.path("../frame_head").scwin.gFormWarnContn; //공동공시 유의사항

scwin.vScrenID = 'ULDSTF10107.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// 로그인 사용자정보로 공시처리가능여부 체크 
scwin.fn_getProcButtonYN = function() {
    var url = "/Viewer.do?method=getProcBtnShowYn" + "&inputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&outputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&ACPT_NO=" + scwin.gAcptNo + "&DUTY_GRP_TP=" + scwin.gDutyGrp + "&DEP_CD=" + scwin.gDepCd;
    dts_btnshow.DataID = encodeURI(url);
    dts_btnshow.reset();
};


// 처리버튼 생성여부 
scwin.fn_showProcButton = function(pDutyProcYn, pGrnlProcYn, pCloseYn) {
    //alert(gDutyYn+","+pDutyProcYn+","+pGrnlProcYn+","+pCloseYn+","+gJobTitle);	

    if (scwin.gAcptNo != '') {
        // 가져온접수번호가 있으면 처리함.

        // 마감전일때
        if (pCloseYn == 'N') {
            if (scwin.gFormWarnContn != "") {
                label_WARN_CONTN.childNodes[0].innerText = scwin.gFormWarnContn;
            }
            if (scwin.gJobTitle == '40') {
                //부서장권한 제거 2013.03.26
                $c.stf.showObj(panel_1, false);
            } else {
                // 로그한 사용자가 당번이면서 접수문서가 당번그룹에 해당할 경우
                if ((scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') && pDutyProcYn == 'Y') {
                    // 패널라운드 처리	
                    $c.libRoundPanel.PanelToGroupBox(panel_1);
                    $c.stf.showObj(panel_1, true);
                } else {
                    // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
                    //if (gJobTitle == '09' || gJobTitle == '40') {
                    if (scwin.gJobTitle == '09') {
                        // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.(팀장은 담당종목팀만 처리가능으로 변경 2013.03.26)
                        $c.cm.PanelToGroupBox(panel_1); // 패널라운드 처리	
                        $c.stf.showObj(panel_1, true);
                    } else {
                        // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                        if (pGrnlProcYn == 'Y') {
                            $c.libRoundPanel.PanelToGroupBox(panel_1); // 패널라운드 처리	
                            $c.stf.showObj(panel_1, true);
                        } else {
                            $c.stf.showObj(panel_1, false);
                        }
                    }
                }
            }
        } else {
            // 마감후일때
            $c.stf.showObj(panel_1, false);
        }
    }
};




// 검토처리하기 
scwin.fn_DsclStudyAffact = function(gStatCd) {
    //alert(vTrnsmtp +"="+gAcptNo);
    if (scwin.gAcptNo == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    dts_AcptProcs.insertRow();
    dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    dts_AcptProcs.setCellData(1, "AFFACT_PROCS_STAT_CD", gStatCd);
    var vMethod = "processDisclosureStudyAffact";
    if (dts_AcptProcs.getCellData(1, "ACPT_NO") == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    var gConfirmStr = "";
    if (gStatCd == "10") {
        gConfirmStr = "사후검토 처리 하시겠습니까?";
    } else {
        gConfirmStr = "정정요구검토 처리 하시겠습니까?";
    }
    var vAnswer = confirm(gConfirmStr);
    if (vAnswer == true) {
        trs_AcptProcs.Action = "/DisclosureStudyAffact.do?method=" + vMethod + "&inputMessageId=DSCLPROC_AFFACT_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo;
        trs_AcptProcs.KeyName = "toinb_dataid4";
        trs_AcptProcs.KeyValue = "JSP(I:pInput=dts_AcptProcs)";
        trs_AcptProcs.Post();
    }
};



// 뷰어 닫고,  검색목록 reload
scwin.fn_CloseParentReload = function() {
    // 화면닫기
    $c.frame.path("../").fn_PvdSearch();
    $c.frame.path("../").fn_CloseWin();
};



//화면오픈 정정요구서작성화면
scwin.fn_MoveBizProcPage = async function() {
    var vUrl = "/submission/searchDisclosureDocument.do?method=searchChangeInqueryDocument";
    if ($c.frame.path("/top") != undefined) {
        $c.frame.path("/top").WinOpen("정정공시요구서작성", vUrl, "정정공시요구서작성", 1275, 785);
    } else {
        await $c.frame.CreateFrame("정정공시요구서작성", vUrl, "정정공시요구서작성", 10, 10, 1275, 785, "window", 0, 0, true);
    }
};
scwin.dts_btnshow_OnLoadCompleted = function(rowcount) {
    scwin.fn_showProcButton(dts_btnshow.getCellData(1, "DUTY_PROC_YN"), dts_btnshow.getCellData(1, "GRNL_PROC_YN"), dts_btnshow.getCellData(1, "CLOSE_YN"));
};
scwin.dts_btnshow_OnLoadError = function() {
    //alert('dts_btnshow.OnFail() :' + dts_btnshow.ErrorMsg);
    $c.win.alert("사용자 정보를 가져오는데 실패하였습니다.");
};
scwin.trs_AcptProcs_OnSuccess = function() {
    if (scwin.gProcsCd != '') {
        if (scwin.gProcsCd == "10") {
            $c.win.alert("성공적으로 사후검토 처리 되었습니다.");
        } else {
            $c.win.alert("성공적으로 정정요구검토 처리 되었습니다. ");
            scwin.fn_MoveBizProcPage();
        }
    }
    scwin.fn_CloseParentReload();
};
scwin.trs_AcptProcs_OnFail = function() {
    //alert('trs_AcptProcs.OnFail() :' + trs_AcptProcs.ErrorMsg);
    if (scwin.gProcsCd != '') {
        if (scwin.gProcsCd == "10") {
            $c.win.alert("사후검토 처리에 실패하였습니다.");
        } else {
            $c.win.alert("정정요구검토 처리에 실패하였습니다. ");
        }
    }
};
scwin.img_affstudy_onclick = function() {
    //사후검토
    scwin.gProcsCd = '10';
    scwin.fn_DsclStudyAffact(scwin.gProcsCd);
};
scwin.img_affreq_onclick = function() {
    // 정정요구검토
    scwin.gProcsCd = '20';
    scwin.fn_DsclStudyAffact(scwin.gProcsCd);
};
scwin.img_close_onclick = function() {
    $c.frame.path("../").fn_CloseWin();
};
scwin.img_print_onclick = function() {
    //fn_PrintFormCall();
    $c.frame.path("../frame_head").fn_PrintOpen();
};
scwin.gform_onload = function() {
    // 로그인 사용자정보로 공시처리가능여부 체크 
    scwin.fn_getProcButtonYN();

    // 가우스헤더 셋팅
    dts_AcptProcs.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLPROC_AFFACT_IN";
    dts_AcptProcs.reset();
};
